func(h *harnessV1)emit(tx *sql.Tx,actor,project string,task,run Object,kind string,data Object)(int64,error){
 state,err:=singleton(tx,project,"ProjectState");if err!=nil{return 0,err}
 sequence,_:=Num(state,"event_sequence");var maximum int64
 if err=tx.QueryRow("SELECT COALESCE(MAX(sequence),0) FROM outbox WHERE project=?",project).Scan(&maximum);err!=nil{return 0,err}
 if maximum>sequence{sequence=maximum};if sequence==1<<63-1{return 0,errors.New("event sequence exhausted")};sequence++
 payload:=Object{"status":nil,"text":nil,"tool":nil,"task":nil,"error":nil}
 for k,v:=range data{if _,ok:=payload[k];!ok{return 0,errors.New("unknown harness event field")};payload[k]=v}
 eventID:=ID()
 event:=Object{"event_id":eventID,"task_ref":harnessRef(project,Str(task,"id")),"run":harnessRunRef(run),"sequence":strconv.FormatInt(sequence,10),"timestamp":Now(),"kind":kind,"payload":payload}
 artifact,err:=h.c.service.serverArtifactMode(tx,project,actor,"LOG","LIVE",Bytes(Object{"schema":"researchos.harness-event.v1","event":event}),Empty());if err!=nil{return 0,err}
 if err=bump(state);err!=nil{return 0,err};state["event_sequence"]=sequence
 if err=h.c.service.put(tx,"ProjectState",state);err!=nil{return 0,err}
 envelope:=Object{"id":eventID,"project_id":project,"revision":1,"created_at":Now(),"sequence":sequence,"event_type":"TASK_CHANGED","aggregate_ref":Ref(task,"Task"),"actor_id":actor,"correlation_id":eventID,"causation_id":nil,"event_data_artifact_ref":Ref(artifact,"Artifact")}
 envelope["receipt_hash"]=Receipt(envelope)
 if err=h.c.service.put(tx,"EventEnvelope",envelope);err!=nil{return 0,err}
 if _,err=tx.Exec("INSERT INTO outbox(project,sequence,id,body) VALUES(?,?,?,?)",project,sequence,eventID,string(Bytes(envelope)));err!=nil{return 0,err}
 _,err=tx.Exec("INSERT INTO event_state_snapshots(project,event_id,revision,body) VALUES(?,?,?,?)",project,eventID,state["revision"],string(Bytes(state)))
 return sequence,err
}
func(h *harnessV1)readEvents(tx *sql.Tx,project,id string)([]Object,error){
 rows,err:=tx.Query("SELECT body FROM outbox WHERE project=? AND json_extract(body,'$.aggregate_ref.entity_type')='Task' AND json_extract(body,'$.aggregate_ref.id')=? AND json_extract(body,'$.event_data_artifact_ref.id') IS NOT NULL ORDER BY sequence LIMIT 5001",project,id)
 if err!=nil{return nil,err}
 var envelopes []Object
 for rows.Next(){var raw string;if err=rows.Scan(&raw);err!=nil{rows.Close();return nil,err};ev,err:=Decode([]byte(raw));if err!=nil{rows.Close();return nil,err};envelopes=append(envelopes,ev)}
 err=rows.Err();rows.Close();if err!=nil{return nil,err}
 if len(envelopes)>5000{return nil,errors.New("harness event budget exceeded")}
 events:=make([]Object,0,len(envelopes))
 for _,ev:=range envelopes{
  if ev["receipt_hash"]!=Receipt(ev){return nil,errors.New("event receipt changed")}
  ref,ok:=ev["event_data_artifact_ref"].(map[string]any);if !ok{return nil,errors.New("event data missing")}
  artifact,err:=version(tx,project,ref);if err!=nil{return nil,err};var raw []byte
  if err=tx.QueryRow("SELECT bytes FROM uploaded_content WHERE project=? AND storage_key=? AND sealed=1",project,artifact["storage_key"]).Scan(&raw);err!=nil{return nil,err}
  if Digest(raw)!=artifact["content_hash"]{return nil,errors.New("event data seal changed")}
  wrapper,err:=Decode(raw);if err!=nil{return nil,err}
  if wrapper["schema"]!="researchos.harness-event.v1"{continue}
  event,ok:=wrapper["event"].(map[string]any);if !ok{return nil,errors.New("native event malformed")}
  seq,_:=Num(ev,"sequence")
  if event["event_id"]!=ev["id"]||event["sequence"]!=strconv.FormatInt(seq,10)||Hash(event["task_ref"])!=Hash(harnessRef(project,id)){return nil,errors.New("native event binding changed")}
  events=append(events,event)
 }
 return events,nil
}
func(h *harnessV1)Events(ctx context.Context,token string,in HarnessEvents)(Object,error){
 if !harnessLabel(in.ProjectID,128)||!harnessLabel(in.TaskID,128)||in.Limit<1||in.Limit>500{return nil,harnessFail(400,"INVALID_REQUEST","project/task/limit invalid")}
 cursor,err:=HarnessDecimal(in.Cursor,false);if err!=nil{return nil,err}
 tx,p,err:=h.auth(ctx,token,in.ProjectID);if err!=nil{return nil,err};defer tx.Rollback()
 task,record,request,err:=h.record(tx,p.ID,in.ProjectID,in.TaskID);if err!=nil{return nil,err}
 view,err:=h.taskView(tx,in.ProjectID,task,record,request);if err!=nil{return nil,err}
 events,err:=h.readEvents(tx,in.ProjectID,in.TaskID);if err!=nil{return nil,err}
 tail:=int64(0);found:=cursor==0
 for _,event:=range events{seq,_:=HarnessDecimal(Str(event,"sequence"),true);if seq>tail{tail=seq};if seq==cursor{found=true}}
 if cursor>tail||!found{return harnessEnvelope(Object{"task_ref":harnessRef(in.ProjectID,in.TaskID),"events":Empty(),"next_cursor":strconv.FormatInt(tail,10),"has_more":false,"end":view["terminal"],"reset":true,"snapshot":view}),nil}
 page:=Empty();more:=false;next:=cursor;terminalSeen:=false
 for _,event:=range events{seq,_:=HarnessDecimal(Str(event,"sequence"),true);if seq<=cursor{if event["kind"]=="TASK_TERMINAL"{terminalSeen=true};continue};if len(page)>=in.Limit{more=true;break};page=append(page,event);next=seq;if event["kind"]=="TASK_TERMINAL"{terminalSeen=true}}
 return harnessEnvelope(Object{"task_ref":harnessRef(in.ProjectID,in.TaskID),"events":page,"next_cursor":strconv.FormatInt(next,10),"has_more":more,"end":view["terminal"]==true&&!more&&terminalSeen,"reset":false,"snapshot":nil}),nil
}
func(h *harnessV1)Cancel(ctx context.Context,token,project,id string,in HarnessCancel)(Object,error){
 if !harnessLabel(project,128)||!harnessLabel(id,128){return nil,harnessFail(400,"INVALID_REQUEST","project/task required")}
 if err:=in.Validate();err!=nil{return nil,err}
 tx,p,err:=h.auth(ctx,token,project);if err!=nil{return nil,err};defer tx.Rollback()
 hash:=Hash(Object{"task_id":id,"request":in})
 replay,err:=harnessReplay(tx,p.ID,project,"harness:v1:cancel",in.RequestID,hash);if err!=nil||replay!=nil{return replay,err}
 task,record,request,err:=h.record(tx,p.ID,project,id);if err!=nil{return nil,err}
 view,err:=h.taskView(tx,project,task,record,request);if err!=nil{return nil,err}
 revision,_:=Num(task,"revision")
 conflict:=func()error{value:=strconv.FormatInt(revision,10);var run Object;if current,ok:=view["run"].(map[string]any);ok{run=current};return &HarnessError{Status:409,Code:"STATE_CONFLICT",Message:"current task/run changed",TaskRef:harnessRef(project,id),Revision:&value,Run:run}}
 if strconv.FormatInt(revision,10)!=in.ExpectedTaskRevision{return nil,conflict()}
 current,hasRun:=view["run"].(map[string]any)
 if hasRun{if in.ExpectedRunID==nil||*in.ExpectedRunID!=Str(current,"run_id")||*in.ExpectedEpoch!=Str(current,"epoch"){return nil,conflict()}}else if in.ExpectedRunID!=nil{return nil,conflict()}
 disposition:="ALREADY_TERMINAL"
 if view["terminal"]!=true{
  if !hasRun{
   task["status"]="CANCELLED";if err=bump(task);err!=nil{return nil,err};if err=h.c.service.put(tx,"Task",task);err!=nil{return nil,err}
   view,err=h.taskView(tx,project,task,record,request);if err!=nil{return nil,err}
   if _,err=h.emit(tx,p.ID,project,task,nil,"TASK_TERMINAL",Object{"status":"CANCELLED","task":view});err!=nil{return nil,err}
   disposition="CANCELLED_BEFORE_LAUNCH"
  }else{
   run,_,_,err:=h.c.service.runtimeOperation(tx,p,project,Str(current,"run_id"),Object{"reason":"Authenticated Host V1 cancellation"},"cancelRun",ID());if err!=nil{return nil,err}
   task,err=load(tx,project,"Task",id);if err!=nil{return nil,err};view,err=h.taskView(tx,project,task,record,request);if err!=nil{return nil,err}
   if _,err=h.emit(tx,p.ID,project,task,run,"RUN_STATE",Object{"status":"CANCEL_REQUESTED"});err!=nil{return nil,err}
   disposition="CANCEL_REQUESTED"
  }
 }
 response:=harnessEnvelope(Object{"task":view,"disposition":disposition})
 if _,err=tx.Exec("INSERT INTO idempotency(principal,project,operation,key,request_hash,status,body,headers,created_at) VALUES(?,?,?,?,?,200,?,'{}',?)",p.ID,project,"harness:v1:cancel",in.RequestID,hash,string(Bytes(response)),Now());err!=nil{return nil,err}
 return response,tx.Commit()
}

// Harness task ownership is proven by the original Host operation and its
// sealed input; merely naming a generic task harness_turn grants no launch.
func harnessTaskInput(tx *sql.Tx,project string,task Object)(Object,error){
 var principal,requestID,requestHash string
 if err:=tx.QueryRow("SELECT principal,key,request_hash FROM idempotency WHERE project=? AND operation='harness:v1:submit' AND json_extract(body,'$.data.task_ref.task_id')=?",project,task["id"]).Scan(&principal,&requestID,&requestHash);err!=nil{return nil,Fail(403,"FORBIDDEN","original Host Harness submission missing")}
 for _,value:=range Arr(task,"input_refs"){
  ref,ok:=value.(map[string]any);if !ok||ref["entity_type"]!="Artifact"{continue}
  artifact,err:=version(tx,project,ref);if err!=nil{return nil,err};var raw []byte
  if err=tx.QueryRow("SELECT bytes FROM uploaded_content WHERE project=? AND storage_key=? AND sealed=1",project,artifact["storage_key"]).Scan(&raw);err!=nil{return nil,err}
  if Digest(raw)!=artifact["content_hash"]{return nil,Fail(422,"CONTENT_HASH_MISMATCH","native input seal changed")}
  data,err:=Decode(raw);if err!=nil||data["schema"]!="researchos.harness-submit.v1"{continue}
  request,ok:=data["request"].(map[string]any)
  if !ok||data["principal_id"]!=principal||request["request_id"]!=requestID||request["project_id"]!=project||Hash(request)!=requestHash{return nil,Fail(403,"FORBIDDEN","native submission identity changed")}
  return data,nil
 }
 return nil,Fail(403,"FORBIDDEN","native input missing")
}
func(s *Service)nativeHarnessAdmission(tx *sql.Tx,project string,task,runtime Object,requested []any,operation string)(Object,error){
 if task==nil||task["task_type"]!="harness_turn"||runtime["adapter"]!="codex-cli-harness-v1"||runtime["status"]!="AVAILABLE"||operation=="resume"||len(requested)!=1||requested[0]!="start"{return nil,Fail(403,"FORBIDDEN","native readonly Harness scope required")}
 ref,artifact,err:=s.currentRuntimeBinding(tx,project,runtime);if err!=nil{return nil,err}
 profile,err:=runtimeProfileBody(tx,project,artifact);if err!=nil{return nil,err}
 if profile["backend"]!="codex-cli-readonly-v1"||profile["sandbox"]!="codex-permissions-workspace-read-v1"||profile["credential_revision"]!="CLI_OWNED"{return nil,Fail(422,"GATE_FAILED","native Harness profile required")}
 record,err:=harnessTaskInput(tx,project,task);if err!=nil{return nil,err}
 if record["runtime_id"]!=runtime["id"]||Hash(record["profile_ref"])!=Hash(ref)||record["principal_id"]!=profile["harness_owner"]{return nil,Fail(403,"FORBIDDEN","native Task/profile mismatch")}
 principal:=Str(record,"principal_id")
 owner,err:=clientAuthenticatedPrincipal(context.Background(),tx,principal)
 if err!=nil||owner.DeviceID!=""||!owner.HasRole("OWNER")||!owner.Allowed(project,"","",false){return nil,Fail(403,"FORBIDDEN","native Owner authority revoked")}
 root,err:=currentAuthorityRoot(tx,principal);if err!=nil||root!=profile["owner_root"]{return nil,Fail(403,"FORBIDDEN","native Owner lineage changed")}
 request:=record["request"].(map[string]any)
 binding,err:=s.binding(context.Background(),tx,Str(request,"workspace_ref"))
 if err!=nil||binding.PrincipalID!=principal||binding.ProjectID==nil||*binding.ProjectID!=project||binding.Status!=WorkspaceActive{return nil,Fail(403,"FORBIDDEN","native workspace revoked")}
 expires,err:=time.Parse(time.RFC3339Nano,Str(profile,"consent_expires_at"));if err!=nil||!expires.After(time.Now()){return nil,Fail(403,"FORBIDDEN","native Host consent expired")}
 return Object{"admission_kind":"HOST_HARNESS_V1","mode":runtime["measurement_mode"],"runtime_id":runtime["id"],"runtime_ref":Ref(runtime,"RuntimeRegistration"),"profile_ref":ref,"profile_hash":Hash(ref),"profile":profile,"technical_hash":runtimeTechnicalHash(runtime),"qualification_ids":Empty(),"qualification_evidence":Empty(),"permission":Object{"kind":"OWNER_AUTHORIZED_HARNESS_TURN","principal":principal,"workspace_ref":request["workspace_ref"],"scope":"workspace-read"},"credential_revision":"CLI_OWNED","expires_at":profile["consent_expires_at"],"requested_capabilities":requested},nil
}

